// ListRegistryTags lists the tags of a repository through the registry's v2 API.
//
// apiURL is the API base (see the browser's registryAPIURL). Credentials, when
// given, go as Basic auth and, on a 401 that names a Bearer realm, to that
// realm's token endpoint — the flow Docker Hub and most hosted registries use.
// The token is kept for the following pages.
//
// The list is followed across pages: whatever a registry caps a response at,
// and Docker Hub does not, a repository with more tags than one page holds is
// returned whole. This is the one tag lister that speaks the Bearer flow; the
// template client's ListTags (Client.ListTags) reads a registry the user
// configured for templates and only ever sends Basic auth.
func ListRegistryTags(apiURL, repo, username, password string) ([]string, error) {
	return ListRegistryTagsContext(context.Background(), apiURL, repo, username, password)
}

// ListRegistryTagsContext is ListRegistryTags bound to ctx: a cancelled or
// expired context stops the walk, including a request in flight, and the
// returned error wraps the context's error. A context already done sends
// nothing. registryHTTPClient's own timeout still applies per request; when
// both expire, whichever comes first ends the request, and either way the
// error satisfies errors.Is(err, context.DeadlineExceeded).
func ListRegistryTagsContext(ctx context.Context, apiURL, repo, username, password string) ([]string, error) {
	next := fmt.Sprintf("%s/v2/%s/tags/list", strings.TrimSuffix(apiURL, "/"), repo)
	var (
		tags  []string
		token string
	)
	for page := 0; next != ""; page++ {
		if page == maxTagPages {
			return nil, fmt.Errorf("tag list of %s is longer than %d pages", repo, maxTagPages)
		}
		body, link, usedToken, err := registryGETContext(ctx, next, username, password, token)
		if err != nil {
			return nil, err
		}
		token = usedToken
		var result struct {
			Tags []string `json:"tags"`
		}
	if err != nil {
		return ""
	}
	return u.Host
}

// resolveNext is the URL a Link header's rel="next" points to, resolved against
// the page it came with — registries send it as a path — or "" when there is
// none. A next link that leads back to the page just read ends the walk rather
// than looping on it.
func resolveNext(current, link string) string {
	for _, part := range strings.Split(link, ",") {
		target, rel, ok := strings.Cut(strings.TrimSpace(part), ";")
		if !ok || !strings.Contains(rel, `rel="next"`) {
			continue
		}
		target = strings.Trim(strings.TrimSpace(target), "<>")
		base, err := url.Parse(current)
		if err != nil {
			return ""
		}
		ref, err := url.Parse(target)
		if err != nil {
			return ""
		}
		if next := base.ResolveReference(ref).String(); next != current {
			return next
		}
	}
	return ""
}

// exchangeBearerToken fetches a bearer token from the registry's token endpoint.
func exchangeBearerToken(registryURL, challenge, username, password string) (string, error) {
	return exchangeBearerTokenContext(context.Background(), registryURL, challenge, username, password)
}

// checkTokenRealm refuses, before any request to it, a Bearer realm that is
// neither http nor https (a relative realm included). It also refuses an http
// realm when the registry is https or cannot be parsed, whatever the
// credentials: the realm would otherwise receive them (or a token request) in
// clear. A missing or unparsable realm passes: exchangeBearerTokenContext
// reports those. The error names the realm's host only, never its userinfo,
// path or query.
func checkTokenRealm(registryURL, challenge string) error {
	realm, ok := parseBearerChallenge(challenge)["realm"]
	if !ok {
		return nil
	}
	u, err := url.Parse(realm)
	if err != nil {
		return nil
	}
	reg, _ := url.Parse(registryURL)
	switch {
	case u.Scheme == "https":
		return nil
	case u.Scheme == "http" && reg != nil && reg.Scheme != "https":
		return nil
	case u.Hostname() == "":
		return errInsecureTokenRealm
	}
	return fmt.Errorf("%w (%s)", errInsecureTokenRealm, u.Host)
}

// exchangeBearerTokenContext is exchangeBearerToken bound to ctx. It applies
// checkTokenRealm itself, so no caller reaches an insecure realm by skipping
// registryDoContext; registryURL is the registry that sent the challenge.
func exchangeBearerTokenContext(ctx context.Context, registryURL, challenge, username, password string) (string, error) {
	if err := checkTokenRealm(registryURL, challenge); err != nil {
		return "", err
	}
	u, err := tokenEndpoint(challenge)
	if err != nil {
		return "", err
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u, nil)
	if err != nil {
		return "", buildRequestError("build token request", u, err)
	}
	if username != "" && password != "" {
		req.SetBasicAuth(username, password)
	}
	resp, err := registryHTTPClient.Do(req)
	if err != nil {
		return "", fmt.Errorf("fetch token: %w", StripRedirectTarget(err))
	}
	defer func() { _ = resp.Body.Close() }()
	if resp.StatusCode != http.StatusOK {
		return "", &StatusError{Code: resp.StatusCode, Source: SourceToken}
	}
	return readToken(resp.Body)
}

// tokenEndpoint is the URL of the token request a Bearer challenge asks for: its
// realm, with the service and scope it names as the query.
func tokenEndpoint(challenge string) (string, error) {
	params := parseBearerChallenge(challenge)
	realm, ok := params["realm"]
	if !ok {
		return "", fmt.Errorf("bearer challenge missing realm")
	}
	u, err := url.Parse(realm)
	if err != nil {
		// The raw realm may hold a userinfo or a signed query: only the cause stays.
		var ue *url.Error
		if errors.As(err, &ue) {
			err = ue.Err
		}
		return "", fmt.Errorf("parse realm: %w", err)
	}
	q := u.Query()
	if s, ok := params["service"]; ok {
		q.Set("service", s)
	}
	if s, ok := params["scope"]; ok {
		q.Set("scope", s)
	}
	u.RawQuery = q.Encode()
	return u.String(), nil
}

// readToken reads a token endpoint's answer, at most maxTokenResponse bytes, and
// returns the token it holds.
func readToken(body io.Reader) (string, error) {
	data, err := io.ReadAll(io.LimitReader(body, maxTokenResponse+1))
	if err != nil {
		return "", fmt.Errorf("read token response: %w", err)
	}
	if len(data) > maxTokenResponse {
		return "", fmt.Errorf("token response over %d bytes", maxTokenResponse)
	}
	var result struct {
		Token       string `json:"token"`
		AccessToken string `json:"access_token"`
	}
	if err := json.Unmarshal(data, &result); err != nil {
		return "", fmt.Errorf("decode token response: %w", err)
	}
	if result.Token != "" {
		return result.Token, nil
	}
	body, err = io.ReadAll(io.LimitReader(resp.Body, limit+1))
	if err == nil && int64(len(body)) > limit {
		err = errors.New("catalog page over " + strconv.FormatInt(limit, 10) + " bytes")
	}
	if err != nil {
		return nil, "", token, err
	}
	return body, resp.Header.Get("Link"), token, nil
}

